package xyz.block.kotlinformatter

import xyz.block.kotlinformatter.TriggerFormatter.Companion.FormattingResult
import java.io.File
import kotlin.io.path.name
import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.io.TempDir

class TriggerFormatterTest {
  // Replacing 4 spaces with 2 spaces
  private val testFormatter =
    object : Formatter {
      override fun format(code: String): String {
        return code.replace("    ", "  ")
      }
    }

  private val unformattedCode =
    """
    |data class Test(
    |    val a: Int,
    |    val b: Int
    |)"""
      .trimMargin()

  private val formattedCode =
    """
    |data class Test(
    |  val a: Int,
    |  val b: Int
    |)"""
      .trimMargin()

  private fun setupTestFile(rootDir: File, originalFileContent: String): File {
    val file = File(rootDir, "Test.kt")
    file.writeText(originalFileContent)

    GitProcessRunner.run("init")
    GitProcessRunner.run("add", file.path)

    return file
  }

  @Test
  fun `formats a file without staging changes`(@TempDir tempDir: File) {
    TestUtils.withWorkingDir(tempDir) {
      val file = setupTestFile(tempDir, unformattedCode)

      val configs = FormattingConfigs.forWorkingDir(listOf(file.toString()))
      val formattingResult = configs.formattables.map { TriggerFormatter(testFormatter).format(it, configs) }.toSet()

      assertThat(formattingResult).containsExactly(FormattingResult.Formatted(file.toString()))
      assertThat(file.readText()).isEqualTo(formattedCode)
      // Check that change is not staged
      assertThat(GitStagingService.getUnstagedFiles().map { it.name }).containsExactly("Test.kt")
    }
  }

  @Test
  fun `does not format an already formatted file`(@TempDir tempDir: File) {
    TestUtils.withWorkingDir(tempDir) {
      val file = setupTestFile(tempDir, formattedCode)

      val configs = FormattingConfigs.forWorkingDir(listOf(file.toString()))
      val formattingResult = configs.formattables.map { TriggerFormatter(testFormatter).format(it, configs) }.toSet()

      assertThat(formattingResult).containsExactly(FormattingResult.AlreadyFormatted(file.toString()))
      assertThat(file.readText()).isEqualTo(formattedCode)
    }
  }

  @Test
  fun `stage formatting change`(@TempDir tempDir: File) {
    TestUtils.withWorkingDir(tempDir) {
      val file = setupTestFile(tempDir, unformattedCode)

      val configs = FormattingConfigs.forPreCommit(listOf())
      val formattingResult = configs.formattables.map { TriggerFormatter(testFormatter).format(it, configs) }.toSet()
      val stagedChange = TestFixtures.getStagedContent(tempDir)

      assertThat(formattingResult).containsExactly(FormattingResult.Formatted(file.name))
      assertThat(file.readText()).isEqualTo(formattedCode)
      assertThat(stagedChange.values).containsExactly(formattedCode)
    }
  }

  @Test
  fun `format staged blob only for file with staged and unstaged changes`(@TempDir tempDir: File) {
    TestUtils.withWorkingDir(tempDir) {
      val file = setupTestFile(tempDir, unformattedCode)
      val workingDirContent = "blah blah blah"
      file.writeText(workingDirContent)

      val configs = FormattingConfigs.forPreCommit(listOf())
      val formattingResult = configs.formattables.map { TriggerFormatter(testFormatter).format(it, configs) }.toSet()
      val stagedChange = TestFixtures.getStagedContent(tempDir)

      assertThat(formattingResult).containsExactly(FormattingResult.Formatted(file.name))
      // note here the working dir file is not modified by the formatter
      assertThat(file.readText()).isEqualTo(workingDirContent)
      // but the staged file is formatted
      assertThat(stagedChange.values).containsExactly(formattedCode)
    }
  }

  @Test
  fun `does not format or stage change in dry run mode`(@TempDir tempDir: File) {
    TestUtils.withWorkingDir(tempDir) {
      val file = setupTestFile(tempDir, unformattedCode)

      val configs = FormattingConfigs.forWorkingDir(listOf(file.toString()), dryRun = true)
      val formattingResult = configs.formattables.map { TriggerFormatter(testFormatter).format(it, configs) }.toSet()
      val stagedChange = TestFixtures.getStagedContent(tempDir)

      assertThat(formattingResult).containsExactly(FormattingResult.WouldFormat(file.toString()))
      assertThat(file.readText()).isEqualTo(unformattedCode)
      assertThat(stagedChange.values).containsExactly(unformattedCode)
    }
  }

  @Test
  fun `reports error if when formatting fails`(@TempDir tempDir: File) {
    TestUtils.withWorkingDir(tempDir) {
      val file = setupTestFile(tempDir, unformattedCode)

      val configs = FormattingConfigs.forWorkingDir(listOf(file.toString()))
      val formattingException = RuntimeException("Formatter failed")
      val failingFormatter =
        object : Formatter {
          override fun format(code: String): String {
            throw formattingException
          }
        }
      val formattingResult = configs.formattables.map { TriggerFormatter(failingFormatter).format(it, configs) }.toSet()

      val expectedErrorMessage = "Unexpected error formatting ${file}: Formatter failed"
      assertThat(formattingResult)
        .containsExactly(FormattingResult.FormattingError(file.path, expectedErrorMessage, formattingException))
      assertThat(file.readText()).isEqualTo(unformattedCode)
    }
  }

  @Test
  fun `handles moved files correctly between pre-commit and pre-push`(@TempDir tempDir: File) {
    TestUtils.withWorkingDir(tempDir) {
      // 1. Create and commit an unformatted file
      val originalFile = setupTestFile(tempDir, unformattedCode)
      TestUtils.setupGitUser()
      GitProcessRunner.run("commit", "-m", "Initial commit with unformatted file")

      // 2. Move the file using Git commands
      val newFileName = "Test2.kt"
      GitProcessRunner.run("mv", originalFile.path, newFileName)

      // 3. pre-commit check should format
      val preCommitConfigs = FormattingConfigs.forPreCommit(listOf())
      val preCommitResult = preCommitConfigs.formattables.map { TriggerFormatter(testFormatter).format(it, preCommitConfigs) }.toSet()
      assertThat(preCommitResult).containsExactly(FormattingResult.Formatted(newFileName))

      // 4. Commit the move
      GitProcessRunner.run("commit", "-m", "Move file")

      // 5. pre-push check should detect already formatted
      val prePushConfigs = FormattingConfigs.forPrePush(listOf(), dryRun = true, commitRef = "HEAD")
      val prePushResult = prePushConfigs.formattables.map { TriggerFormatter(testFormatter).format(it, prePushConfigs) }.toSet()
      assertThat(prePushResult).containsExactly(FormattingResult.AlreadyFormatted(newFileName))
    }
  }
}

package xyz.block.kotlinformatter

import java.io.File
import java.nio.charset.StandardCharsets.UTF_8
import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.io.TempDir

class FormattingConfigsTest {

  @Test
  fun `convert list of filenames to files`(@TempDir tempDir: File) {
    // Create server directory and files
    val serverDir = tempDir.resolve("server").apply { mkdirs() }
    val serverExample1 = serverDir.resolve("Example1.kt").apply { writeText("", UTF_8) }
    val serverExample2 = serverDir.resolve("Example2.kt").apply { writeText("", UTF_8) }
    serverDir.resolve("Example3.kt").apply { writeText("", UTF_8) }
    serverDir.resolve("build.gradle.kts").apply { writeText("", UTF_8) }

    // Create build directory and file
    val serviceBuildDir = serverDir.resolve("build").apply { mkdirs() }
    val buildExample = serviceBuildDir.resolve("BuildExample.kt").apply { writeText("", UTF_8) }

    val configs =
      FormattingConfigs.forWorkingDir(
        listOf(serverExample1.toString(), serverExample2.toString(), buildExample.toString(), "other_file.kt")
      )

    // Exclude other_file.kt and BuildExample.kt in service/build directory
    assertThat(configs.formattables)
      .containsExactlyInAnyOrder(FormattableFile(serverExample1), FormattableFile(serverExample2))
  }

  @Test
  fun `expand directory to list of files`(@TempDir tempDir: File) {
    // Create server directory and files
    val serverDir = tempDir.resolve("server").apply { mkdirs() }
    val serverExample1 = serverDir.resolve("Example1.kt").apply { writeText("", UTF_8) }
    val serverExample2 = serverDir.resolve("Example2.kt").apply { writeText("", UTF_8) }

    serverDir.resolve("build.gradle.kts").apply { writeText("", UTF_8) }

    // Create build directory and file
    serverDir.resolve("build").apply { mkdirs() }.resolve("BuildExample.kt").writeText("", UTF_8)

    // Create client directory and files
    val clientDir = tempDir.resolve("client").apply { mkdirs() }
    clientDir.resolve("Example1.kt").apply { writeText("", UTF_8) }
    clientDir.resolve("Example2.kt").apply { writeText("", UTF_8) }

    val configs = FormattingConfigs.forWorkingDir(listOf(serverDir.toString()))

    // Exclude kt files in service/build directory and client directory
    assertThat(configs.formattables)
      .containsExactlyInAnyOrder(FormattableFile(serverExample1), FormattableFile(serverExample2))
  }

  @Test
  fun `include files in non Gradle build dir`(@TempDir tempDir: File) {
    // Create server directory and files
    val serverDir = tempDir.resolve("server").apply { mkdirs() }
    val serverExample1 = serverDir.resolve("Example1.kt").apply { writeText("", UTF_8) }

    // Create build directory and file but without build.gradle.kts
    val buildDir = serverDir.resolve("build").apply { mkdirs() }
    val buildExample = buildDir.resolve("BuildExample.kt").apply { writeText("", UTF_8) }

    val configs = FormattingConfigs.forWorkingDir(listOf(serverDir.toString()))
    assertThat(configs.formattables)
      .containsExactlyInAnyOrder(FormattableFile(serverExample1), FormattableFile(buildExample))
  }

  @Test
  fun `include all staged files when running in precommit mode`(@TempDir tempDir: File) {
    // Create server directory and files
    val serverDir = tempDir.resolve("server").apply { mkdirs() }
    val serverExample1 = serverDir.resolve("Example1.kt").apply { writeText("", UTF_8) }
    val serverExample2 = serverDir.resolve("Example2.kt").apply { writeText("", UTF_8) }
    serverDir.resolve("Example3.kt").apply { writeText("", UTF_8) }
    serverDir.resolve("build.gradle.kts").apply { writeText("", UTF_8) }

    // Create build directory and file
    val serviceBuildDir = serverDir.resolve("build").apply { mkdirs() }
    val buildExample = serviceBuildDir.resolve("BuildExample.kt").apply { writeText("", UTF_8) }

    // Note that we are staging a build file, it should be included in the formattables
    TestUtils.withWorkingDir(serverDir) {
      GitProcessRunner.run("init")
      GitProcessRunner.run("add", serverExample1.toString(), serverExample2.toString(), buildExample.toString())

      val configs = FormattingConfigs.forPreCommit(listOf())
      assertThat(getFormattableBlobPaths(configs.formattables))
        .containsExactlyInAnyOrder(
          serverExample1.relativeTo(serverDir).toPath(),
          serverExample2.relativeTo(serverDir).toPath(),
          buildExample.relativeTo(serverDir).toPath(),
        )
    }
  }

  @Test
  fun `filter staged files by directory when running in precommit mode`(@TempDir tempDir: File) {
    // Create server directory and files
    val serverDir = tempDir.resolve("server").apply { mkdirs() }
    val subdir = serverDir.resolve("subdir").apply { mkdirs() }
    val serverExample1 = serverDir.resolve("Example1.kt").apply { writeText("", UTF_8) }
    val serverExample2 = subdir.resolve("Example2.kt").apply { writeText("", UTF_8) }
    serverDir.resolve("Example3.kt").apply { writeText("", UTF_8) }
    serverDir.resolve("build.gradle.kts").apply { writeText("", UTF_8) }

    // Create build directory and file
    val serviceBuildDir = serverDir.resolve("build").apply { mkdirs() }
    val buildExample = serviceBuildDir.resolve("BuildExample.kt").apply { writeText("", UTF_8) }

    // Note that we are staging a build file, it should be included in the formattables
    TestUtils.withWorkingDir(serverDir) {
      GitProcessRunner.run("init")
      GitProcessRunner.run("add", serverExample1.toString(), serverExample2.toString(), buildExample.toString())

      val configs = FormattingConfigs.forPreCommit(listOf("subdir"))
      assertThat(getFormattableBlobPaths(configs.formattables))
        .containsExactlyInAnyOrder(serverExample2.relativeTo(serverDir).toPath())
    }
  }

  @Test
  fun `filter staged files from a different directory in precommit mode`(@TempDir tempDir: File) {
    // Create server directory and files
    val serverDir = tempDir.resolve("server").apply { mkdirs() }
    val subdir = serverDir.resolve("some/subdir").apply { mkdirs() }
    val serverExample1 = serverDir.resolve("Example1.kt").apply { writeText("", UTF_8) }
    val serverExample2 = subdir.resolve("Example2.kt").apply { writeText("", UTF_8) }

    TestUtils.withWorkingDir(serverDir) {
      GitProcessRunner.run("init")
      GitProcessRunner.run("add", serverExample1.toString(), serverExample2.toString())

      TestUtils.withWorkingDir(serverDir.resolve("some")) {
        val configs = FormattingConfigs.forPreCommit(listOf())
        assertThat(getFormattableBlobPaths(configs.formattables))
          .containsExactlyInAnyOrder(
            serverExample1.relativeTo(serverDir).toPath(),
            serverExample2.relativeTo(serverDir).toPath(),
          )
      }
    }
  }

  @Test
  fun `filter staged files relative to current directory in precommit mode`(@TempDir tempDir: File) {
    // Create server directory and files
    val serverDir = tempDir.resolve("server").apply { mkdirs() }
    val subdir = serverDir.resolve("some/subdir").apply { mkdirs() }
    val serverExample1 = serverDir.resolve("Example1.kt").apply { writeText("", UTF_8) }
    val serverExample2 = subdir.resolve("Example2.kt").apply { writeText("", UTF_8) }

    TestUtils.withWorkingDir(serverDir) {
      GitProcessRunner.run("init")
      GitProcessRunner.run("add", serverExample1.toString(), serverExample2.toString())

      TestUtils.withWorkingDir(serverDir.resolve("some")) {
        // This simulates running `format --pre-commit .` inside the `server/some` directory,
        // so only the Example2.kt file should be included in the formattables.
        val configs = FormattingConfigs.forPreCommit(listOf("."))
        assertThat(getFormattableBlobPaths(configs.formattables))
          .containsExactlyInAnyOrder(serverExample2.relativeTo(serverDir).toPath())
      }
      TestUtils.withWorkingDir(serverDir.resolve("some")) {
        // This simulates running `format --pre-commit ..` inside the `server/some` directory,
        // so both files should be included in the formattables.
        val configs = FormattingConfigs.forPreCommit(listOf(".."))
        assertThat(getFormattableBlobPaths(configs.formattables))
          .containsExactlyInAnyOrder(
            serverExample1.relativeTo(serverDir).toPath(),
            serverExample2.relativeTo(serverDir).toPath(),
          )
      }
    }
  }

  @Test
  fun `filter committed files relative to current directory in pre-push mode`(@TempDir tempDir: File) {
    // Create server directory and files
    val serverDir = tempDir.resolve("server").apply { mkdirs() }
    val subdir = serverDir.resolve("some/subdir").apply { mkdirs() }
    val serverExample1 = serverDir.resolve("Example1.kt").apply { writeText("", UTF_8) }
    val serverExample2 = subdir.resolve("Example2.kt").apply { writeText("", UTF_8) }
    val serverExample3 = subdir.resolve("Example3.kt").apply { writeText("", UTF_8) }
    subdir.resolve("Example4.kt").apply { writeText("", UTF_8) }

    TestUtils.withWorkingDir(serverDir) {
      GitProcessRunner.run("init")
      GitProcessRunner.run("add", serverExample1.toString(), serverExample2.toString())
      TestUtils.setupGitUser() // needed for commit to work on CI
      GitProcessRunner.run("commit", "-m", "Initial commit")
      // Neither Example3.kt nor Example4.kt are committed, so they should not show up in the list
      // of pre-push formattables.
      GitProcessRunner.run("add", serverExample3.toString())

      TestUtils.withWorkingDir(serverDir.resolve("some")) {
        // This simulates running `format --pre-push .` inside the `server/some` directory,
        // so only the Example2.kt file should be included in the formattables.
        val configs = FormattingConfigs.forPrePush(listOf("."), dryRun = true, commitRef = "HEAD")
        assertThat(getFormattableBlobPaths(configs.formattables))
          .containsExactlyInAnyOrder(serverExample2.relativeTo(serverDir).toPath())
      }
      TestUtils.withWorkingDir(serverDir.resolve("some")) {
        // This simulates running `format --pre-push ..` inside the `server/some` directory,
        // so both files should be included in the formattables.
        val configs = FormattingConfigs.forPrePush(listOf(".."), dryRun = true, commitRef = "HEAD")
        assertThat(getFormattableBlobPaths(configs.formattables))
          .containsExactlyInAnyOrder(
            serverExample1.relativeTo(serverDir).toPath(),
            serverExample2.relativeTo(serverDir).toPath(),
          )
      }
    }
  }

  private fun getFormattableBlobPaths(formattables: List<Formattable>) = formattables.map { formattable ->
    when (formattable) {
      is FormattableBlob -> formattable.path
      is FormattableBlobAndFile -> formattable.path()
      else -> throw IllegalStateException("Unexpected formattable type: ${formattable.javaClass}")
    }
  }

}

package xyz.block.kotlinformatter

import xyz.block.kotlinformatter.GitStagingService.getStagedFiles
import xyz.block.kotlinformatter.GitStagingService.getStagedFormattableBlobs
import java.io.File
import java.nio.file.Path

internal object TestFixtures {
  internal data class TestDirectoryFiles(
    val rootDir: File,
    val generatedWireSource: File,
    val gradleBuildFile: File,
    val mainAlreadyFormatted: File,
    val mainExample1: File,
    val testExample1Test: File,
    val libRandomFile: File,
    val libExample2: File,
    val libExample3: File,
    val edgecaseSpaces: File,
  )

  // Original File Content
  internal val gradleBuildFileContent =
    """
        plugins {
            kotlin("jvm") version "1.4.32"
        }

        repositories {
            mavenCentral()
        }

        dependencies {
            implementation(kotlin("stdlib"))
        }
    """
      .trimIndent()
  internal val generatedWireSourceContent = "fun buildExample()    =   println(\"Build Example\")\n"
  internal val mainAlreadyFormattedContent = "fun foo() = println(\"Hello World\")\n"
  internal val mainExample1Content = "fun  foo()=println(\"Example 1\")"
  internal val testExample1TestContent = "fun test() {     println(\"Example 1 Test\")}"
  internal val libRandomFileContent = "This is a text file."
  internal val libExample2Content = "fun bar()  =  println(\"Example 2\")"
  internal val libExample3Content = "fun bar()  =  println(\"Example 3\")"
  internal val edgecaseSpacesContent = "fun bar()  =  println(\"File with spaces\")"

  // Formatted File Content
  internal val formattedMainExample1Content = "fun foo() = println(\"Example 1\")\n"
  internal val formattedTestExample1TestContent = "fun test() {\n  println(\"Example 1 Test\")\n}\n"
  internal val formattedLibExample2Content = "fun bar() = println(\"Example 2\")\n"
  internal val formattedLibExample3Content = "fun bar() = println(\"Example 3\")\n"
  internal val formattedEdgecaseSpacesContent = "fun bar() = println(\"File with spaces\")\n"

  /**
   * Directory and File Structure:
   * ```
   * └── project/
   *     ├── .gitignore
   *     ├── build.gradle.kts
   *     ├── build/
   *     │   └── generated/
   *     │       └── source/
   *     │           └── wire/
   *     │               └── BuildExample.kt
   *     ├── src/
   *     │   ├── main/
   *     │   │   └── kotlin/
   *     │   │       ├── AlreadyFormatted.kt
   *     │   │       └── Example1.kt
   *     │   └── test/
   *     │       └── kotlin/
   *     │           └── Example1Test.kt
   *     ├── lib/
   *     │   ├── randomFile.txt
   *     │   ├── Example2.kt
   *     │   └── Example3.kt
   *     └── edgecases/
   *         └─── file with spaces.kt
   * ```
   */
  fun setupTestDirectory(root: File): TestDirectoryFiles {
    val projectDir = File(root, "project").apply { mkdirs() }

    // Add gitignore file
    File(projectDir, ".gitignore").apply {
      writeText(
        """
            # Ignore build directories
            /build/

            # Ignore IntelliJ IDEA project files
            .idea/
            *.iml

            # Ignore log files
            *.log
        """
          .trimIndent()
      )
    }

    val gradleBuildFile = File(projectDir, "build.gradle.kts").apply { writeText(gradleBuildFileContent) }

    // Create build/generated/source/wire directory and add Kotlin file
    val buildWireDir = File(projectDir, "build/generated/source/wire").apply { mkdirs() }
    val generatedWireSource = File(buildWireDir, "BuildExample.kt").apply { writeText(generatedWireSourceContent) }

    val srcMainKotlin = File(root, "project/src/main/kotlin").apply { mkdirs() }
    val srcTestKotlin = File(root, "project/src/test/kotlin").apply { mkdirs() }
    val lib = File(root, "project/lib").apply { mkdirs() }
    val edgecases = File(root, "project/edgecases").apply { mkdirs() }

    val mainAlreadyFormattedFile =
      File(srcMainKotlin, "AlreadyFormatted.kt").apply { writeText(mainAlreadyFormattedContent) }
    val mainExample1 = File(srcMainKotlin, "Example1.kt").apply { writeText(mainExample1Content) }
    val testExample1Test = File(srcTestKotlin, "Example1Test.kt").apply { writeText(testExample1TestContent) }
    val libRandomFile = File(lib, "RandomFile.txt").apply { writeText(libRandomFileContent) }
    val libExample2 = File(lib, "Example2.kt").apply { writeText(libExample2Content) }
    val libExample3 = File(lib, "Example3.kt").apply { writeText(libExample3Content) }
    val edgecaseSpaces = File(edgecases, "file with spaces.kt").apply { writeText(edgecaseSpacesContent) }

    return TestDirectoryFiles(
      rootDir = projectDir,
      generatedWireSource = generatedWireSource,
      gradleBuildFile = gradleBuildFile,
      mainAlreadyFormatted = mainAlreadyFormattedFile,
      mainExample1 = mainExample1,
      testExample1Test = testExample1Test,
      libRandomFile = libRandomFile,
      libExample2 = libExample2,
      libExample3 = libExample3,
      edgecaseSpaces = edgecaseSpaces,
    )
  }

  /**
   * Compiles a map of file paths to their content for all staged files.
   *
   * @return A map of file paths as strings to their content.
   */
  fun getStagedContent(gitRoot: File): Map<String, String> {
    return getStagedFormattableBlobs(gitRoot, getStagedFiles()).associate { it.name() to it.read() }
  }

  fun blob(path: String) = FormattableBlob(Path.of(path), "100644", "somehash")
}

package xyz.block.kotlinformatter

import java.io.File

object TestUtils {
  internal fun <T> withWorkingDir(dir: File, block: () -> T): T {
    val oldWorkingDir = System.getProperty("user.dir")
    try {
      System.setProperty("user.dir", dir.absolutePath)
      return block()
    } finally {
      System.setProperty("user.dir", oldWorkingDir)
    }
  }

  internal fun setupGitUser() {
    GitProcessRunner.run("config", "user.name", "Testy McTestface")
    GitProcessRunner.run("config", "user.email", "test@squareup.com")
  }

  internal fun addPrecommitHook(rootDir: File) {
    rootDir.resolve(".git/hooks/pre-commit").apply {
      writeText(
        """
          |#!/usr/bin/env bash
          |set -euo pipefail
          |java -jar ${System.getenv("JAR_UNDER_TEST")} --pre-commit .
          |
          """
          .trimMargin()
      )
      setExecutable(true, false)
    }
    GitProcessRunner.run("config", "--local", "core.hooksPath", ".git/hooks")
  }
}

package xyz.block.kotlinformatter

import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.AfterEach
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.Timeout
import org.junit.jupiter.api.io.TempDir
import java.io.File
import java.net.Socket
import java.nio.file.Path
import java.time.Duration
import java.time.Instant
import kotlin.concurrent.thread

class TestSystemExiter : SystemExiter {
  var exitCalled = false
  var lastExitStatus = -1

  override fun exit(status: Int) {
    exitCalled = true
    lastExitStatus = status
  }
}

class DaemonTest {
  private lateinit var daemon: Daemon
  private lateinit var daemonThread: Thread
  private lateinit var testExiter: TestSystemExiter

  @TempDir
  lateinit var tempDir: Path

  @BeforeEach
  fun setup() {
    testExiter = TestSystemExiter()
    daemon = Daemon(
      systemExiter = testExiter,
      idleTimeout = IDLE_TIMEOUT,
      maxRuntime = MAX_RUNTIME,
      timeoutCheckerInterval = TIMEOUT_CHECKER_INTERVAL,
      workingDir = tempDir
    )

    // Start daemon in a separate thread
    daemonThread = thread(start = true) {
      try {
        daemon.start()
      } catch (e: Exception) {
        // Ignore exceptions from normal shutdown
        if (!e.message?.contains("Socket closed")!!) {
          throw e
        }
      }
    }

    // Wait for daemon to start (max 1 second)
    var attempts = 0
    while (!daemon.isRunning() && attempts < 20) {
      Thread.sleep(50)
      attempts++
    }

    assertThat(daemon.isRunning()).isTrue()
  }

  @AfterEach
  fun tearDown() {
    daemon.stop()
